#include <stdio.h>
#include <stdint.h>
#include <string.h>
typedef int (*op)(int);
int op_right(int x) { return 2 * x; }
int op_wrong(void) { return 99; }
int main(int argc, char **argv) {
  if (argc > 1 && strcmp(argv[1], "self") == 0) {
    printf("%p %p\n", (void *)op_right, (void *)op_wrong);
    return 0;
  }
  unsigned long long addr;
  if (scanf("%lli", &addr) != 1) {
    printf("no input\n");
    return 2;
  }
  op fp = (op)addr;
  int r = fp(21);
  printf("result -> %d\n", r);
  return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <string.h>
struct Base { virtual int apply(int) = 0; virtual ~Base() {} };
struct Derived : Base { int apply(int x) override { return x * 2; } };
struct Evil { virtual int evil(int) { return 99; } };
int main(int argc, char **argv) {
  if (argc > 1 && strcmp(argv[1], "self") == 0) {
    static Derived d;
    static Evil e;
    printf("%p %p\n", (void *)&d, (void *)&e);
    return 0;
  }
  unsigned long long p;
  if (scanf("%lli", &p) != 1) return 2;
  Base *b = (Base *)p;
  int r = b->apply(21);
  printf("result -> %d\n", r);
  return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

__attribute__((noinline)) void sink(void) {
  printf("HACKED: process returned into sink\n");
  exit(0);
}

/* The vulnerable function: no bounds check, attacker-controlled length. */
__attribute__((noinline)) int process(char *line, size_t len) {
  char buf[16];
  int auth = 0;
  memcpy(buf, line, len);   /* overflow when len > 16 */
  return auth + 1;
}

int main(int argc, char **argv) {
  if (argc > 1 && strcmp(argv[1], "self") == 0) {
    printf("%p\n", (void *)sink);
    return 0;
  }
  unsigned long long addr;
  if (scanf("%lli", &addr) != 1) return 2;
  char payload[64];
  size_t n = 0;
  for (int i = 0; i < 24; i++) payload[n++] = 'A';
  for (int i = 0; i < 4; i++) {      /* spray: cover wherever the
                                        saved return address sits */
    memcpy(payload + n, &addr, 8);
    n += 8;
  }
  payload[n] = 0;
  int r = process(payload, n);
  printf("process returned %d\n", r);
  return 0;
}

#include <stdio.h>

__attribute__((noinline)) int classify(int x) {
    if (x < 0)
        return 100 - x;
    if (x < 50)
        return x * 2;
    return x / 2 + 5;
}

int main(void) {
    int v;
    if (scanf("%d", &v) != 1) return 2;
    printf("classify(%d)=%d\n", v, classify(v));
    return 0;
}

