// minishield-fuzz.cpp — fuzz the learner's minishield-flatten pass.
//
// Each libFuzzer input is the text of an LLVM IR module. Per run:
//   1. parse and verify it (most mutations die here);
//   2. check the input contract: a defined i32 @f(i32), no @main, and no
//      non-intrinsic declares — a self-contained pure function;
//   3. run the plugin's function(minishield-flatten) pipeline on a clone
//      (the real plugin from build/libMiniShield.so, loaded once via
//      PassPlugin::Load);
//   4. verify the flattened module;
//   5. behavioral differential: compile the original and the flattened
//      module into native binaries (each linked with a wrapper main that
//      prints f(x) for a fixed argument battery) and compare the output
//      on every argument.
//
// Trap semantics:
//   - the original binary traps on some argument -> the input is
//     undefined behavior even before the pass -> skip, not a bug;
//   - the flattened binary traps or disagrees where the original was
//     healthy -> behavioral regression -> report and return 1 (libFuzzer
//     marks the input interesting and keeps it in the corpus).

#include "llvm/IR/Function.h"
#include "llvm/IR/LLVMContext.h"
#include "llvm/IR/Module.h"
#include "llvm/IR/Verifier.h"
#include "llvm/IRReader/IRReader.h"
#include "llvm/Passes/PassBuilder.h"
#include "llvm/Plugins/PassPlugin.h"
#include "llvm/Support/Error.h"
#include "llvm/Support/MemoryBuffer.h"
#include "llvm/Support/SourceMgr.h"
#include "llvm/Support/raw_ostream.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <memory>
#include <optional>
#include <string>
#include <vector>

#include <fcntl.h>
#include <sys/wait.h>
#include <unistd.h>

using namespace llvm;

namespace {

// The plugin under test: build/libMiniShield.so by default, or the
// MINISHIELD_PLUGIN environment variable (the negative control points it
// at the mutant build).
std::string pluginPath() {
    if (const char *env = getenv("MINISHIELD_PLUGIN"))
        return env;
    return "build/libMiniShield.so";
}

// The argument battery: fixed, nothing excluded — INT_MIN and INT_MAX,
// zero, negatives, and the small values a branch condition flips on.
const int kBattery[] = {
    -2147483648, -1000, -42, -8, -1, 0, 1, 2, 7, 8, 42, 127, 128, 1000,
    4096, 2147483647};
const int kBatteryN = sizeof(kBattery) / sizeof(kBattery[0]);

const char *kWorkdir = "/tmp/minishield-fuzz";

// The wrapper main: a separate translation unit so the module under test
// never needs to provide one.
const char *kWrapper = R"WRAP(
#include <stdio.h>
#include <stdlib.h>
extern int f(int);
int main(int argc, char **argv) {
    if (argc != 2)
        return 98;
    int x = atoi(argv[1]);
    printf("%d\n", f(x));
    return 0;
}
)WRAP";

void writeFile(const std::string &path, const std::string &content) {
    FILE *fp = fopen(path.c_str(), "w");
    if (!fp)
        return;
    fputs(content.c_str(), fp);
    fclose(fp);
}

std::string moduleText(const Module &M) {
    std::string out;
    raw_string_ostream OS(out);
    M.print(OS, nullptr);
    return out;
}

// Run a command, capturing stdout; pclose returns the wait status.
struct RunResult {
    int status;
    std::string output;
};
RunResult runCapture(const std::string &cmd) {
    RunResult r;
    FILE *p = popen(cmd.c_str(), "r");
    if (!p) {
        r.status = -1;
        return r;
    }
    char buf[8192];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), p)) > 0)
        r.output.append(buf, n);
    r.status = pclose(p);
    return r;
}

// A trap: killed by a signal, or a nonzero exit (the wrapper returns 0
// on every healthy call).
bool trapped(const RunResult &r) {
    return r.status == -1 || WIFSIGNALED(r.status) ||
           (WIFEXITED(r.status) && WEXITSTATUS(r.status) != 0);
}

// Redirect fd 2 to /dev/null (and back) around the plugin's run, so a
// fuzzing session stays readable.
void silenceStderr(bool on) {
    static int saved = -1;
    if (on) {
        if (saved == -1)
            saved = dup(2);
        int fd = open("/dev/null", O_WRONLY);
        dup2(fd, 2);
        close(fd);
    } else if (saved != -1) {
        dup2(saved, 2);
        close(saved);
        saved = -1;
    }
}

// ---- plugin + PassBuilder, initialized once ----------------------------
// gPB is deliberately leaked: the plugin's pass-plugin is linked against the
// system libstdc++ while this harness uses the conda one, so destroying the
// PassBuilder's cross-world std::function callbacks at exit is not safe.
// The fuzzer process is short-lived, so a one-off leak is harmless.
PassBuilder *gPB;
bool gInit = false;
void initOnce() {
    if (gInit)
        return;
    gInit = true;
    system("mkdir -p /tmp/minishield-fuzz");
    std::string path = pluginPath();
    Expected<PassPlugin> plugin = PassPlugin::Load(path);
    if (!plugin) {
        fprintf(stderr, "[fuzz] cannot load plugin '%s': %s\n", path.c_str(),
                toString(plugin.takeError()).c_str());
        exit(2);
    }
    gPB = new PassBuilder(); // leaked on purpose (see above)
    plugin->registerPassBuilderCallbacks(*gPB);
}

// Parse and verify; null on any failure. The context must outlive the
// module (the module's destructor reaches back into it).
std::unique_ptr<Module> parseModule(const std::string &irText,
                                    LLVMContext &Ctx) {
    MemoryBufferRef MBR(irText, "<fuzz-input>");
    SMDiagnostic Err;
    std::unique_ptr<Module> M = parseIR(MBR, Err, Ctx);
    if (!M)
        return nullptr;
    std::string V;
    raw_string_ostream OS(V);
    if (verifyModule(*M, &OS))
        return nullptr;
    return M;
}

// Parse, verify, and apply the input contract. Returns null for any
// input that is not a self-contained pure i32 @f(i32).
std::unique_ptr<Module> parseGate(const std::string &irText,
                                  LLVMContext &Ctx) {
    std::unique_ptr<Module> M = parseModule(irText, Ctx);
    if (!M)
        return nullptr;
    // (Module::getFunction is not used: name-map lookups are unreliable for
    // parser-built modules in this LLVM; iteration is version-proof.)
    Function *F = nullptr;
    for (const Function &Fn : *M) {
        if (Fn.getName() == "f")
            F = const_cast<Function *>(&Fn);
        if (Fn.getName() == "main" && !Fn.isDeclaration())
            return nullptr; // the wrapper provides main
    }
    if (!F || F->isDeclaration())
        return nullptr;
    if (!F->getReturnType()->isIntegerTy(32) || F->arg_size() != 1 ||
        !F->arg_begin()->getType()->isIntegerTy(32))
        return nullptr;
    for (const Function &Fn : *M)
        if (Fn.isDeclaration() && !Fn.isIntrinsic())
            return nullptr;
    return M;
}

// Run function(minishield-flatten) on the module. Returns false (with a
// message in errOut) if the pipeline fails or the result does not verify.
bool runPipeline(Module &M, bool live, std::string &errOut) {
    // The standard PassBuilder setup: register the known analyses and
    // cross-register the proxies before running any pipeline.
    LoopAnalysisManager LAM;
    FunctionAnalysisManager FAM;
    CGSCCAnalysisManager CGAM;
    ModuleAnalysisManager MAM;
    gPB->registerModuleAnalyses(MAM);
    gPB->registerFunctionAnalyses(FAM);
    gPB->registerLoopAnalyses(LAM);
    gPB->registerCGSCCAnalyses(CGAM);
    gPB->crossRegisterProxies(LAM, FAM, CGAM, MAM);
    ModulePassManager MPM;
    Error E = gPB->parsePassPipeline(MPM, "function(minishield-flatten)");
    if (E) {
        errOut = toString(std::move(E));
        return false;
    }
    if (!live)
        silenceStderr(true);
    MPM.run(M, MAM);
    if (!live)
        silenceStderr(false);
    std::string V;
    raw_string_ostream OS(V);
    if (verifyModule(M, &OS)) {
        errOut = "verify failed after the pass:\n" + V;
        return false;
    }
    return true;
}

enum class DiffResult { kOk, kSkip, kRegression };

struct Diff {
    std::vector<RunResult> before, after;
    size_t firstBad;
};

// Compile both modules and run the battery.
DiffResult differential(const std::string &beforeText,
                        const std::string &afterText, Diff &diff) {
    writeFile(std::string(kWorkdir) + "/before.ll", beforeText);
    writeFile(std::string(kWorkdir) + "/after.ll", afterText);
    writeFile(std::string(kWorkdir) + "/wrapper.c", kWrapper);

    auto compile = [](const std::string &ll, const std::string &bin) {
        std::string cmd = "clang-23 -o " + bin + " " + ll + " " +
                          std::string(kWorkdir) + "/wrapper.c 2>/dev/null";
        return system(cmd.c_str()) == 0;
    };
    if (!compile(std::string(kWorkdir) + "/before.ll",
                 std::string(kWorkdir) + "/before_bin"))
        return DiffResult::kSkip; // the original does not even build
    if (!compile(std::string(kWorkdir) + "/after.ll",
                 std::string(kWorkdir) + "/after_bin")) {
        diff.firstBad = 0;
        return DiffResult::kRegression; // the flattening broke compilation
    }

    for (int i = 0; i < kBatteryN; ++i) {
        char arg[24];
        snprintf(arg, sizeof(arg), "%d", kBattery[i]);
        diff.before.push_back(
            runCapture(std::string(kWorkdir) + "/before_bin " + arg));
        diff.after.push_back(
            runCapture(std::string(kWorkdir) + "/after_bin " + arg));
        if (trapped(diff.before.back()))
            return DiffResult::kSkip; // undefined behavior before the pass
        if (trapped(diff.after.back()) ||
            diff.before.back().output != diff.after.back().output) {
            diff.firstBad = i;
            return DiffResult::kRegression;
        }
    }
    return DiffResult::kOk;
}

// The first whole line of text containing needle ("" when absent).
std::string findLine(const std::string &text, const char *needle) {
    size_t pos = 0;
    while ((pos = text.find(needle, pos)) != std::string::npos) {
        size_t start = (pos == 0) ? 0 : text.rfind('\n', pos - 1) + 1;
        size_t end = text.find('\n', pos);
        std::string line = text.substr(start, end - start);
        size_t a = line.find_first_not_of(" \t");
        if (a != std::string::npos)
            return line.substr(a);
        pos = end + 1;
    }
    return "";
}

void report(const std::string &irText, const std::string &afterText,
            const Diff &d, const std::string &pipelineErr) {
    fprintf(stderr,
            "\n[fuzz] BEHAVIORAL REGRESSION: minishield-flatten changed "
            "the behavior of @f\n");
    fprintf(stderr, "[fuzz] input module (%zu bytes):\n%s\n", irText.size(),
            irText.c_str());
    if (!pipelineErr.empty()) {
        fprintf(stderr, "[fuzz] %s\n", pipelineErr.c_str());
        return;
    }
    // Re-run the pass with stderr live so its diagnostics are visible.
    LLVMContext Ctx;
    std::unique_ptr<Module> M = parseGate(irText, Ctx);
    if (M) {
        std::string liveErr;
        fprintf(stderr, "[fuzz] pass diagnostics (re-run live):\n");
        runPipeline(*M, /*live=*/true, liveErr);
    }
    for (size_t i = 0; i <= d.firstBad && i < d.before.size(); ++i) {
        char arg[24];
        snprintf(arg, sizeof(arg), "%d", kBattery[(int)i]);
        if (i == d.firstBad) {
            if (trapped(d.after[i]))
                fprintf(stderr,
                        "[fuzz] battery arg %s: original healthy, flattened "
                        "traps (signal %d)\n",
                        arg, WTERMSIG(d.after[i].status));
            else {
                std::string b = d.before[i].output, a = d.after[i].output;
                while (!b.empty() && b.back() == '\n')
                    b.pop_back();
                while (!a.empty() && a.back() == '\n')
                    a.pop_back();
                fprintf(stderr,
                        "[fuzz] battery arg %s: original=%s flattened=%s\n",
                        arg, b.c_str(), a.c_str());
            }
            break;
        }
    }
    std::string store = findLine(afterText, "ptr %ms.state");
    if (!store.empty())
        fprintf(stderr, "[fuzz] flattened module carries: %s\n",
                store.c_str());
}

} // namespace

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    initOnce();
    std::string irText(reinterpret_cast<const char *>(data), size);

    // One context for the whole run; it must outlive every module.
    LLVMContext Ctx;

    // 1. + 2. parse, verify, shape gate.
    std::unique_ptr<Module> M = parseGate(irText, Ctx);
    if (!M)
        return 0;

    // 3. + 4. the pass on a clone (re-parsed from the canonical text,
    // since this LLVM has no Module::clone).
    std::string beforeText = moduleText(*M);
    std::unique_ptr<Module> M2 = parseModule(beforeText, Ctx);
    if (!M2)
        return 0;
    std::string pipelineErr;
    if (!runPipeline(*M2, /*live=*/false, pipelineErr)) {
        report(irText, "", Diff{}, pipelineErr);
        return 1;
    }

    // 5. the behavioral differential.
    std::string afterText = moduleText(*M2);
    Diff diff;
    DiffResult r = differential(beforeText, afterText, diff);
    if (r == DiffResult::kSkip)
        return 0;
    if (r == DiffResult::kRegression) {
        report(irText, afterText, diff, "");
        return 1;
    }
    return 0;
}
